//\
fn add_to(a: &mut Vec<u32>, b: &Vec<u32>) {
//\
    let mut carry: u32 = 0;
//\
    if a.len() < b.len() { a.resize(b.len(), 0); }
//\
    for i in 0..a.len() {
//\
        let mut s = a[i] + carry;
//\
        if i < b.len() { s += b[i]; }
//\
        carry = s / 1000000000;
//\
        a[i] = s % 1000000000;
//\
    }
//\
    if carry != 0 { a.push(carry); }
//\
}
//\
fn main() {
//\
    let args: Vec<String> = std::env::args().collect();
//\
    if args.len() < 2 { return; }
//\
    let n: u64 = args[1].trim().parse().unwrap();
//\
    let mut a: Vec<u32> = vec![1];
//\
    let mut b: Vec<u32> = vec![1];
//\
    for _ in 0..n {
//\
        let mut c = a.clone();
//\
        add_to(&mut c, &b);
//\
        a = b;
//\
        b = c;
//\
    }
//\
    let mut out = String::new();
//\
    out.push_str(&a[a.len() - 1].to_string());
//\
    let mut i = a.len() - 1;
//\
    while i > 0 {
//\
        i -= 1;
//\
        out.push_str(&format!("{:09}", a[i]));
//\
    }
//\
    println!("{}", out);
//\
}
